def is_complex_expr(expr):
    for m in '()&|!*':
        if m in expr:
            return True
    return False


def get_exclude_match_expr(pattern):
    if pattern == "*":
        return lambda d: True
    elif pattern.startswith("r:"):
        reg = re.compile(pattern[2:])
        return reg.match
    else:
        return lambda d: d == pattern


